/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.extern.slf4j.Slf4j;

/**
 * Channel {@code log}: a warning in the log of the application. Useful in development and as the
 * default channel; its logger is in the observability package, so it never becomes an issue.
 */
@ApplicationScoped
@Slf4j
public class LogAlertChannel implements AlertChannel {

  @Override
  public boolean accepts(final String channel) {
    return "log".equals(channel);
  }

  @Override
  public void deliver(final AlertNotification notification) {
    log.warn("[alert {}] {}: {} {}", notification.status(), notification.ruleName(),
        notification.summary(), notification.link());
  }
}
